from fastapi import FastAPI
from fastapi.responses import StreamingResponse
import time

app = FastAPI()

# A generator function — it YIELDS pieces one at a time
def stream_words():
    words = ["Hello! ", "I ", "am ", "streaming ", "words ", "one ", "by ", "one. ", "Cool, ", "right?"]
    for word in words:
        yield f"data: {word}\n\n"  # SSE format: 'data: ...' + two newlines
        time.sleep(0.3)  # Small pause between words (simulates AI thinking)
    yield "data: [DONE]\n\n"  # Tell the client we're finished

@app.get("/stream")
def stream_endpoint():
    return StreamingResponse(
        stream_words(),
        media_type="text/event-stream"  # Tells the browser 'this is a stream'
    )

# When you visit /stream, you'll see words appear one by one!
# Instead of waiting for ALL words, you see each word as it's ready.

