from fastapi import FastAPI, Request, HTTPException
from collections import defaultdict
import time

app = FastAPI()

# Simple Rate Limiter
class SimpleRateLimiter:
    def __init__(self, max_requests: int, window_seconds: int):
        self.max_requests = max_requests
        self.window = window_seconds
        self.requests = defaultdict(list)  # {user_id: [timestamp1, timestamp2, ...]}

    def is_allowed(self, user_id: str) -> bool:
        now = time.time()

        # Remove old timestamps (outside the window)
        self.requests[user_id] = [
            t for t in self.requests[user_id]
            if now - t < self.window
        ]

        # Check if user has exceeded the limit
        if len(self.requests[user_id]) >= self.max_requests:
            return False  # Too many requests!

        # Record this request
        self.requests[user_id].append(now)
        return True  # Allowed!

# Allow 5 requests per 60 seconds
limiter = SimpleRateLimiter(max_requests=5, window_seconds=60)

@app.post("/chat")
def chat(request: Request):
    client_ip = request.client.host  # Identify user by IP address

    if not limiter.is_allowed(client_ip):
        raise HTTPException(
            status_code=429,
            detail="Too many requests! Please wait a minute and try again."
        )

    return {"reply": "Here is your AI response!"}

