# ========== APP SETUP ==========
app = FastAPI(title="My AI API", version="1.0")

# CORS — so the frontend can talk to us
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_methods=["*"],
    allow_headers=["*"],
)

# ========== RATE LIMITING ==========
request_counts = defaultdict(list)

@app.middleware("http")
async def rate_limit(request: Request, call_next):
    client_ip = request.client.host
    now = time.time()
    request_counts[client_ip] = [t for t in request_counts[client_ip] if now - t < 60]
    if len(request_counts[client_ip]) >= 20:  # 20 requests per minute
        raise HTTPException(status_code=429, detail="Too many requests")
    request_counts[client_ip].append(now)
    return await call_next(request)

# ========== MODELS ==========
class ChatRequest(BaseModel):
    message: str
    model: str = "gpt-4o-mini"

# ========== AUTH ==========
API_KEYS = {"sk-test-123": "demo-user"}

def verify_key(x_api_key: str = Header()):
    if x_api_key not in API_KEYS:
        raise HTTPException(status_code=401, detail="Invalid API key")
    return API_KEYS[x_api_key]

# ========== ENDPOINTS ==========
@app.get("/health")
def health():
    return {"status": "healthy", "version": "1.0"}

@app.post("/chat")
def chat(request: ChatRequest, x_api_key: str = Header()):
    user = verify_key(x_api_key)
    return {"user": user, "reply": f"AI response to: {request.message}"}

@app.post("/chat/stream")
def stream_chat(request: ChatRequest, x_api_key: str = Header()):
    verify_key(x_api_key)
    def generate():
        words = f"Great question about {request.message}! Here is a detailed answer.".split()
        for word in words:
            yield f"data: {json.dumps({'text': word + ' '})}\n\n"
            time.sleep(0.15)
        yield "data: [DONE]\n\n"
    return StreamingResponse(generate(), media_type="text/event-stream")

from fastapi import FastAPI, Depends, HTTPException, Header

app = FastAPI()

# ---- The dependency function ----
def get_current_user(x_api_key: str = Header()):
    """This function runs BEFORE every protected endpoint."""
    valid_keys = {"key_123": "Alice", "key_456": "Bob"}
    if x_api_key not in valid_keys:
        raise HTTPException(status_code=401, detail="Invalid API key")
    return valid_keys[x_api_key]  # Returns the username

